{
  "loopspec": "0.1",
  "id": "draft-refine",
  "meta": {
    "name": "draft-refine",
    "version": "0.1.0",
    "description": "Generate, score against a rubric, and refine until the score clears the bar."
  },
  "pattern": "evaluator-optimizer",
  "inputs": {
    "goal": {
      "type": "string",
      "required": true
    }
  },
  "state": {
    "store": "journal",
    "vars": {
      "score": {
        "type": "number",
        "init": 0
      },
      "rounds": {
        "type": "int",
        "init": 0
      }
    }
  },
  "body": [
    {
      "id": "improve",
      "kind": "agent",
      "harness": "cli",
      "prompt": "Improve the artifact toward: ${inputs.goal}. Current score ${state.score}.",
      "on_done": {
        "incr": "rounds"
      }
    },
    {
      "id": "evaluate",
      "kind": "agent",
      "harness": "llm",
      "prompt": "Evaluate factual accuracy against supplied sources. Check each material claim, identify missing citations, and give actionable corrections. Return JSON {score: number, failures: []}, with score between 0 and 1. Unsupported material claims cap the score at 0.5. Never invent sources.",
      "save": {
        "score": "$.score"
      }
    }
  ],
  "terminate": {
    "signal": "llm-judge",
    "until": "${state.score >= 0.85}"
  },
  "caps": {
    "max_iterations": 8,
    "budget": {
      "tokens": 200000,
      "usd": 5,
      "wallclock": "1h"
    },
    "on_cap_exceeded": "breakpoint"
  },
  "target": {
    "runtime": "standalone",
    "emit": [
      "cli",
      "skill",
      "doctor"
    ]
  },
  "schedule": {
    "mode": "manual"
  },
  "observe": {
    "trace": "journal"
  }
}
